// LED yak söndür: D2'deki LED saniyede bir yanıp söner.
// Not: ESP32 DevKit'in üstündeki mavi LED de D2'ye bağlıdır; o da yanıp söner.
const int LED_PIN = 2;

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  digitalWrite(LED_PIN, HIGH);
  Serial.println("Yandi");
  delay(1000);
  digitalWrite(LED_PIN, LOW);
  Serial.println("Sondu");
  delay(1000);
}
